1	// src/lib/plattform/geodaten/scoring.js
2	//
3	// Scoring-Engine der Flächenakquise (reine Funktionen, Client + Server). Bewertet eine Kandidatenfläche –
4	// eine Parzelle oder einen zusammenhängenden Verbund mehrerer Parzellen/Schläge – mit 0–100 Punkten und
5	// Begründung. Gegenstück in Python (identische Regeln und Konstanten, gemeinsame Testfälle):
6	//   Backend-Import/dienste/geodaten/geodaten/scoring.py  ·  tests/faelle.json
7	//
8	// Kriterien (Höchstpunkte): Größe 20 · Form 8 · Neigung/Exposition 12 · Nutzung 8 · Siedlungsabstand 8 ·
9	// Netz (Trassenlänge) 22 · Netzanschlusskosten 8 · Widmungslage 10 · Einstrahlung 4 = 100.
10	// Abzüge: Schutzgebiete (Nähe/Überdeckung), knappe Netzkapazität. K.-o.-Kriterien deckeln den Punktwert
11	// (zu klein, Kern-Schutzgebiet, zu steil).
12	//
13	// Netzanschlusskosten: Logik des Netzanschluss-Rechners (src/lib/rechner/netzanschluss.js, FREIFLAECHE.netz).
14	// Alle Werte sind Schätzungen für die Vorauswahl – maßgeblich sind Netzbetreiber-Auskunft und Standortprüfung.
15	
16	import { FREIFLAECHE, PACHT } from "../../invest/markt.js";
17	import { rechneNetzanschluss, ebeneFuer } from "../../rechner/netzanschluss.js";
18	import { distanzM } from "./geo.js";
19	
20	export const SCORING_VERSION = "2026-09-30.2"; // .2: Deutschland/Schweiz (EEG-Kulisse, BauGB-Privilegierung, Richtplan, FFF)
21	
22	export const GEWICHTE = { groesse: 20, form: 8, neigung: 12, nutzung: 8, siedlung: 8, netz: 22, kosten: 8, widmung: 10, einstrahlung: 4 };
23	
24	/**
25	 * Gewichte je Land (Summe jeweils 100). Österreich = GEWICHTE. Deutschland und Schweiz erhalten das Kriterium
26	 * „Flächenkulisse“ (DE: EEG-Förderkulisse § 37 EEG; CH: kantonale Eignungsgebiete/vorbelastete Standorte) – die übrigen
27	 * Kriterien werden proportional skaliert (Punkte = Grundpunkte × Landesgewicht / Grundgewicht).
28	 */
29	export const GEWICHTE_LAND = {
30	  AT: GEWICHTE,
31	  DE: { groesse: 18, form: 7, neigung: 10, nutzung: 6, siedlung: 7, netz: 20, kosten: 7, widmung: 8, kulisse: 14, einstrahlung: 3 },
32	  CH: { groesse: 18, form: 7, neigung: 11, nutzung: 6, siedlung: 7, netz: 20, kosten: 7, widmung: 8, kulisse: 12, einstrahlung: 4 },
33	};
34	
35	/**
36	 * Flächenkulisse (Anteile 0–1 der Kandidatenfläche, aus Geodaten des Dienstes bzw. der Demo):
37	 *   DE  randstreifenAnteil – ≤ 500 m längs Autobahn/Schienenweg (§ 37 Abs. 1 Nr. 2 lit. c EEG 2023) – förderfähig
38	 *       benachteiligtAnteil – Acker/Grünland im benachteiligten Gebiet (§ 37 Abs. 1 Nr. 3 lit. h/i, § 37c EEG; Länder-Opt-out möglich)
39	 *       moorAnteil         – entwässerter, landwirtschaftlich genutzter Moorboden mit Wiedervernässung (§ 37 Abs. 1 Nr. 3 lit. e EEG)
40	 *       konversionAnteil   – Konversions-/versiegelte Fläche (§ 37 Abs. 1 Nr. 2 lit. a/b EEG)
41	 *       privilegiertAnteil – ≤ 200 m längs Autobahn/zweigleisiger Hauptbahn (§ 35 Abs. 1 Nr. 8 lit. b BauGB) → Widmungslage
42	 *   CH  eignungAnteil      – kantonales Eignungsgebiet/Richtplan-Festsetzung für Solaranlagen
43	 *       vorbelastet        – an Verkehrs-/Infrastrukturanlagen (vorbelasteter Standort)
44	 *       fffAnteil          – Fruchtfolgefläche (Sachplan FFF) → Abzug
45	 * Faktor je Kulisse (Anteil × Faktor, Maximum zählt): Randstreifen/Konversion 1,0 · benachteiligt 0,85 · Moor 0,7.
46	 */
47	export const KULISSE = {
48	  DE: { randstreifenM: 500, privilegiertM: 200, faktor: { konversion: 1, randstreifen: 1, benachteiligt: 0.85, moor: 0.7 } },
49	  CH: { faktor: { eignung: 1, vorbelastet: 0.6 }, fffAbzug: 8 },
50	};
51	
52	/** Näherung Trassenlänge: Luftlinie × Umwegfaktor + Zuschlag je Querung (Straße ab Landesstraße, Bahn, Fluss) */
53	export const TRASSE = { umwegFaktor: 1.25, querungZuschlagM: 150, suchradiusKm: 25 };
54	
55	/** Schwellen der Bewertung */
56	export const SCHWELLEN = {
57	  mindestHa: 2, // darunter K.-o. (Deckel)
58	  idealHa: [5, 50],
59	  maxNeigungGrad: 15, // darüber K.-o. (Deckel)
60	  siedlungAbstandM: [100, 300], // < 100 m kritisch, ≥ 300 m voll
61	  ampel: { gruen: 65, gelb: 45 },
62	};
63	
64	/** Schutzgebietsarten: kern = Ausschluss (Deckel), sonst Abzug */
65	export const SCHUTZ_ARTEN = {
66	  nationalpark: { label: "Nationalpark", kern: true, abzugNah: 6 },
67	  natura2000: { label: "Natura 2000 / Europaschutzgebiet", kern: true, abzugNah: 6 },
68	  naturschutz: { label: "Naturschutzgebiet", kern: true, abzugNah: 5 },
69	  wasserschutz: { label: "Wasserschutz-/Schongebiet", kern: false, abzug: 10, abzugNah: 0 },
70	  landschaftsschutz: { label: "Landschaftsschutzgebiet", kern: false, abzug: 8, abzugNah: 2 },
71	  sonstig: { label: "sonstiges Schutzgebiet", kern: false, abzug: 5, abzugNah: 0 },
72	};
73	
74	/** Netzknoten-Arten (aus OSM power=substation/transformer bzw. Netzbetreiber-Daten) */
75	export const KNOTEN_ARTEN = {
76	  uew: { label: "Umspannwerk Übertragungsnetz (220/380 kV)", kurz: "UW 380/220 kV" },
77	  uw110: { label: "Umspannwerk 110 kV / Mittelspannung", kurz: "UW 110 kV" },
78	  ms: { label: "Umspann-/Schaltwerk Mittelspannung", kurz: "UW MS" },
79	  trafo: { label: "Trafostation (MS/NS)", kurz: "Trafostation" },
80	};
81	
82	/** Welche Knoten kommen für eine Ebene in Frage (msLeitung: Einschleifen nahe MS-Netzpunkt) */
83	const KNOTEN_FUER_EBENE = { msLeitung: ["trafo", "ms", "uw110"], uwMs: ["uw110"], hs: ["uw110", "uew"] };
84	
85	/** Ertrag kWh/kWp je Bundesland (PVGIS, aus src/data/regionen/*.js – ertrag.kwhProKwp) */
86	export const ERTRAG = {
87	  Burgenland: 1210, Kärnten: 1240, Niederösterreich: 1190, Oberösterreich: 1130, Salzburg: 1140, Steiermark: 1220, Tirol: 1370, Vorarlberg: 1130, Wien: 1190,
88	  _AT: 1120, _DE: 1020, _CH: 1050,
89	  // Deutschland je Bundesland (PVGIS, src/data/regionen/*.js – ertrag.kwhProKwp)
90	  "Baden-Württemberg": 1130, Bayern: 1130, Berlin: 1050, Brandenburg: 1070, Bremen: 1000, Hamburg: 1010, Hessen: 1090, "Mecklenburg-Vorpommern": 1040,
91	  Niedersachsen: 980, "Nordrhein-Westfalen": 1060, "Rheinland-Pfalz": 1110, Saarland: 1080, Sachsen: 1080, "Sachsen-Anhalt": 1080, "Schleswig-Holstein": 980, Thüringen: 1070,
92	};
93	
94	/**
95	 * Widmungsregeln je Bundesland (Stand der Regionaldaten 29.09.2026, src/data/regionen/*.js):
96	 *   art "uw_radius": Zone = Radius um Umspannwerke (OÖ Kriterienkatalog: energiewirtschaftliche Priorität 1 bis 5 km, 2 bis 7,5 km)
97	 *   art "zonen":     Zone = verordnete Zonen als Geodaten (NÖ SekRop PV, Bgld. Eignungszonen, Stmk. SAPRO Vorrangzonen)
98	 *   art "einzelfall": keine landesweite Zonierung – Einzelfallprüfung (Sbg. Kennzeichnung mit Punktesystem, Ktn. max. 4 ha …)
99	 *   maxHaAusserhalb: Größengrenze außerhalb der Zonen (NÖ 2 ha), maxHa: Obergrenze je Widmung (Ktn. 4 ha)
100	 */
101	export const WIDMUNG = {
102	  Oberösterreich: { art: "uw_radius", zoneKm: 5, angrenzendKm: 7.5, text: "Kriterienkatalog PV-FFA: energiewirtschaftliche Priorität 1 (≤ 5 km zum Umspannwerk) bzw. 2 (≤ 7,5 km); Bodenfruchtbarkeit Stufe 4–5 im Einzelfall prüfen (DORIS)." },
103	  Niederösterreich: { art: "zonen", angrenzendM: 200, maxHaAusserhalb: 2, text: "SekRop PV: 116 Zonen (je Zone 5 ha, mit Ökologiekonzept 10 ha); außerhalb höchstens 2 ha, Zusammenrechnung im 200-m-Umkreis." },
