131	/** Netzanschlusskosten (Rechner-Logik) für Leistung, Trassenlänge und Kapazität */
132	export function netzkosten(mwp, trasseKm, { ebene = "auto", kapazitaet = "unbekannt", land = "at" } = {}) {
133	  const r = rechneNetzanschluss({ mwp: Math.max(0.1, mwp), km: Math.max(0, trasseKm), ebene, kapazitaet: ["frei", "knapp"].includes(kapazitaet) ? kapazitaet : "unbekannt", land });
