137	/**
138	 * Bester Netzknoten für eine Fläche: alle geeigneten Knoten im Suchradius, Auswahl nach geschätzten
139	 * Anschlusskosten (nicht nur Entfernung). `knoten` = [{ id, name, art, spannungKv, kapazitaet, lon, lat }].
140	 * Liefert { knoten, luftlinieM, trasseM, kosten, ebene } oder null.
141	 */
142	export function besterKnoten(punkt, mwp, knoten, { querungen = () => 0, land = "at" } = {}) {
143	  const ebene = ebeneFuer(mwp);
144	  const arten = KNOTEN_FUER_EBENE[ebene];
145	  let best = null;
146	  for (const k of knoten) {
147	    if (!arten.includes(k.art)) continue;
148	    const luft = distanzM(punkt, [k.lon, k.lat]);
149	    if (luft > TRASSE.suchradiusKm * 1000) continue;
150	    const tr = trasseM(luft, querungen(k));
151	    const kosten = netzkosten(mwp, tr / 1000, { ebene: k.art === "trafo" || k.art === "ms" ? "msLeitung" : ebene, kapazitaet: k.kapazitaet, land });
