153	    const wert = kosten.summe * strafe;
154	    if (!best || wert < best.wert || (wert === best.wert && luft < best.luftlinieM)) best = { knoten: k, luftlinieM: Math.round(luft), trasseM: tr, kosten, ebene: kosten.ebene, wert };
155	  }
156	  if (best) delete best.wert;
157	  return best;
158	}
