160	/** Nächster Knoten einer Art (für Anzeige „nächstes Umspannwerk“) */
161	export function naechsterKnoten(punkt, knoten, arten = ["uw110", "uew"]) {
162	  let best = null;
163	  for (const k of knoten) {
164	    if (!arten.includes(k.art)) continue;
165	    const d = distanzM(punkt, [k.lon, k.lat]);
166	    if (!best || d < best.luftlinieM) best = { knoten: k, luftlinieM: Math.round(d) };
167	  }
168	  return best;
169	}
